import { planSprites, spriteCss } from '@fodt/sprite-sheet';

// Sizes are in pixels; the names only become class names.
const plan = planSprites(
  [
    { name: 'home.png', width: 16, height: 16 },
    { name: 'search.png', width: 24, height: 24 },
  ],
  { layout: 'grid', padding: 2 },
);
// plan.width and plan.height are the size of the sheet; plan.placements[i] has x, y, width, height and className.
console.log(spriteCss(plan)); // .sprite-home { background-position: 0 0; width: 16px; height: 16px; } and so on
